`),l(574,"span",7),u(575,"        remove"),f(),u(576," "),l(577,"span",7),u(578,"dead"),f(),l(579,"span",11),u(580,"-"),f(),l(581,"span",7),u(582,"ends"),f(),l(583,"span",8),u(584,"("),f(),l(585,"span",7),u(586,"newly"),f(),u(587," "),l(588,"span",7),u(589,"created"),f(),u(590," "),l(591,"span",7),u(592,"sinks"),f(),u(593," "),l(594,"span",12),u(595,"\u2260"),f(),u(596," "),l(597,"span",8),u(598,"("),f(),l(599,"span",7),u(600,"t"),f(),l(601,"span",8),u(602,"))"),f(),u(603,`
